import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"31、【咸】 艮下兑上","description":"周易阐真 - 31、【咸】 艮下兑上","frontmatter":{"title":"31、【咸】 艮下兑上","description":"周易阐真 - 31、【咸】 艮下兑上"},"headers":[],"relativePath":"zh/classics/chanzhen/032.md","filePath":"zh/classics/chanzhen/032.md"}'),s={name:"zh/classics/chanzhen/032.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：咸，感也。柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平；观其所感，而天地万物之情可见矣！</p></blockquote><h1 id="_31、【咸】-艮下兑上" tabindex="-1">31、【咸】 艮下兑上 <a class="header-anchor" href="#_31、【咸】-艮下兑上" aria-label="Permalink to “31、【咸】 艮下兑上”">​</a></h1><p>初六：咸其拇。</p><p>六二：咸其腓，凶，居吉。</p><p>九三：咸其股，执其随，往吝。</p><p>九四：贞吉，悔亡。憧憧往来，朋从尔思。</p><p>九五：咸其脢，无悔。</p><p>上六：咸其辅颊舌。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：山上有泽，咸。君子以虚受人。</p><p>咸者，感也。上兑泽，下艮山，是山上有泽也。泽本虚，山本高，高而能虚，咸之象也。</p><p>君子有见于此，知山上不虚，不能有泽；人心不虚，不能感物。以是虚其己之所有，而受益于人焉。紫阳云：“休施巧伪为功力，认取他家不死方。”他者，人也。人非世间之凡人，乃我本来不死之真人，因交后天，走于兑家，掩埋已久，迷而不返。间或一顾，学者执着后天，当面错过，不能受之。此其故，皆由不能炼己。不能炼己，私欲满腔，茅塞灵窍，实而不虚，总有人来，无处容纳。修道君子，炼己持心，除去一切后有滓质，而心虚矣。心虚，则先天之气自虚无中来，即能受人之益而实其腹。我以虚感，彼以实应，小往而大来，金丹自然凝结，亦如高山，上虚受泽之润，有不期然而然者。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>拇，茂后反。腓，音肥。憧，音同。脢，音枚。颊，音劫。</p><p>咸者，感也。卦德上兑悦，下艮止，刚止于内，柔悦于外，悦以止为体，止以悦为用，有阴阳相应之义，故谓咸。此调和阴阳之卦，承上坎卦而来。坎者，阴陷其阳，阳不健而阴不顺，阴阳不交，此调和之功不可缺。但调和阴阳，贵乎自然，不贵乎勉强。自然者，无心之感也。勉强者，有心之感也。无心之感，阴阳相和，咸无不感；有心之感，阴阳各别，感之有限，故咸有亨道也。咸道虽亨，然无心有无心之是非，有心有有心之是非，不得以枯木寒灰之无心，即谓咸之亨道。枯木寒灰，纯阴无阳，何得谓感？所谓感者，阴阳潜通之义，如卦象少男少女同处，彼此无心，及至阴阳气足，彼此情动，自然相感。此不感之感，何得以蠢然无心为感乎?</p><p>所谓无心者，无人心也。无人心即有道心，道心是心非心。所谓有心者，有人心也。有人心即无道心，人心非心是心。道心为真，人心为假。用假心则感之不正，阴阳两离；用真心则感之得正，阴阳相通。或阴感而阳应，或阳感而阴应，均以道心为主。以正而感，感以正，而不感以心，何物不可感，何感不能利乎？</p><p>天下感之以正者，莫如贞女。女德主乎贞静，不轻失身于人，必待其佳配而有感。此感之不以心而以正，卦德先止后悦，悦本于止之所由来也。</p><p>修道者，调和阴阳，使阴阳感通，能取贞女之德以为感，则所感皆正，寂然不动，感而遂通。感而遂通，寂然不动，止于其所，逆之顺之，无不遂心如意而得其吉矣。</p><p>初六，性愚志劣，不能炼己持心，妄想大事，如咸其拇矣。拇为足大趾，能动不能行之物，不能行而感之，感不得其正。此动人心之感也。</p><p>六二，柔而无刚，内无道心，为人心所感，如感其腓矣。腓为足肚，宜静不宜动之物。不宜动而妄动，动必招凶。然柔顺得中，虽有人心感动，能居于正，不为人心所感，亦凶中致吉之道。此无道心之感也。</p><p>九三，阳刚宜守道心，不可因外物而动人。心者乃刚而不中，见景生情，如感其股矣。感之于股，不能止于其所，随风起尘，执守不专，有道心而又生人心，以是往而行道，未免见羞于大方。此失道心之感也。</p><p>九四，阳刚本有道心，似乎贞而得吉，又刚而能柔，无感亦无所害，似乎有悔可亡，乃有应。初阴为私欲所牵，道心中又杂人心，外无感而内有感，故憧憧往来，朋从尔思也。朋从之思，因人心而昧道心，性乱情迷，一身皆为人心所摇动。此起人心又昧道心之感也。</p><p>九五，在上阴下阳之际，执两用中，道心常存，人心不生，因物付物，皆出无心，如感其脢矣。脢为背肉，在心之上，近心而离心。道心人心所隔者，毫发之间，感之于脢，虽近于心，而实非心，非心之心，是谓真心。真心非色非空，无方无所，虚灵不昧，是谓无心。以无心感有心，虽有心亦归于无心，无心无悔，浑然天理，止于至善之地，而不迁矣。此守道心而无人心之感也。</p><p>上六，在咸之终，又在悦之极，顺其所欲，务外失内，巧言令色，一切是假，是谓咸其辅颊舌也。凡口、言、笑三者皆动，口动而心未有不动者。此绝无道心全用人心之感也。</p><p>六爻皆有感道，或以人心感，或以道心感，或有道心而又感于人心，或背人心而只感以道心，是非不等，惟止于至善而感之，则道心常存，人心永灭，真阴真阳，隔碍潜通，如磁石吸铁，金丹自虚无中结就矣。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
